class Solution {
  public int longestAlternating(int[] nums) {
    int n = nums.length;
    int[] ue = new int[n], de = new int[n], us = new int[n], ds = new int[n];
    for (int i = 0; i < n; i++) {
      ue[i] = i > 0 && nums[i - 1] < nums[i] ? de[i - 1] + 1 : 1;
      de[i] = i > 0 && nums[i - 1] > nums[i] ? ue[i - 1] + 1 : 1;
    }
    for (int i = n - 1; i >= 0; i--) {
      us[i] = i + 1 < n && nums[i] < nums[i + 1] ? ds[i + 1] + 1 : 1;
      ds[i] = i + 1 < n && nums[i] > nums[i + 1] ? us[i + 1] + 1 : 1;
    }
    int best = 1;
    for (int i = 0; i < n; i++) best = Math.max(best, Math.max(ue[i], de[i]));
    for (int k = 1; k + 1 < n; k++) {
      int x = nums[k - 1], y = nums[k + 1];
      if (x < y) best = Math.max(best, de[k - 1] + ds[k + 1]);
      else if (x > y) best = Math.max(best, ue[k - 1] + us[k + 1]);
    }
    return best;
  }
}
